// Generated by Cube Creator. Editor-only (lives in an "Editor" folder).
// Adds the "Cube Creator" menu:
//   Cube Creator > Set Up Cube       – puts the cube in the open scene (or uses the selected one),
//                                      adds CubeCreatorCube, assigns its config and sets up bloom.
//   Cube Creator > Add Bloom To Scene – URP only: global Volume with Bloom + camera post-processing.
using System;
using System.IO;
using System.Linq;
using UnityEditor;
using UnityEngine;
using UnityEngine.Rendering;
using Object = UnityEngine.Object;

namespace CubeCreator.EditorTools
{
    public static class CubeCreatorSetup
    {
        const string ConfigPrefix = "CubeCreatorConfig_";

        [MenuItem("Cube Creator/Set Up Cube", false, 0)]
        public static void SetUpCube()
        {
            GameObject target = ResolveTarget(out string modelPath);
            if (target == null) return;

            TextAsset config = FindConfig(modelPath);
            if (config == null)
            {
                EditorUtility.DisplayDialog("Cube Creator",
                    "Couldn't find a CubeCreatorConfig_*.json for this model.\n\nKeep the exported CubeCreator_<name> folder together inside Assets, then try again.", "OK");
                return;
            }

            var cube = target.GetComponent<CubeCreatorCube>();
            if (cube == null) cube = Undo.AddComponent<CubeCreatorCube>(target);
            Undo.RecordObject(cube, "Assign Cube Creator config");
            cube.config = config;
            EditorUtility.SetDirty(cube);

            string bloom = TryAddBloom(Path.GetDirectoryName(AssetDatabase.GetAssetPath(config)));

            Selection.activeGameObject = target;
            if (SceneView.lastActiveSceneView != null) SceneView.lastActiveSceneView.FrameSelected();
            EditorUtility.DisplayDialog("Cube Creator",
                $"'{target.name}' is ready.\n\nConfig: {config.name}\n{bloom}\n\nPress Play and click the cube.", "Nice");
        }

        [MenuItem("Cube Creator/Add Bloom To Scene", false, 20)]
        public static void AddBloomMenu()
        {
            EditorUtility.DisplayDialog("Cube Creator", TryAddBloom("Assets"), "OK");
        }

        [MenuItem("Cube Creator/Open Exported README", false, 40)]
        public static void OpenReadme()
        {
            string guid = AssetDatabase.FindAssets("README t:TextAsset")
                .FirstOrDefault(g => AssetDatabase.GUIDToAssetPath(g).Contains("CubeCreator_"));
            if (guid == null) { EditorUtility.DisplayDialog("Cube Creator", "No exported README found.", "OK"); return; }
            AssetDatabase.OpenAsset(AssetDatabase.LoadAssetAtPath<TextAsset>(AssetDatabase.GUIDToAssetPath(guid)));
        }

        // ------------------------------------------------------------------ target

        /// Selected scene object, selected model asset (instantiated), or the only exported model.
        static GameObject ResolveTarget(out string modelPath)
        {
            modelPath = null;
            var selected = Selection.activeObject;

            // 1) a Cube Creator model already in the scene (ignore unrelated selections like the camera)
            if (selected is GameObject go && !EditorUtility.IsPersistent(go))
            {
                GameObject root = PrefabUtility.GetOutermostPrefabInstanceRoot(go);
                if (root == null) root = go;
                var source = PrefabUtility.GetCorrespondingObjectFromOriginalSource(root);
                string sourcePath = source != null ? AssetDatabase.GetAssetPath(source) : null;
                bool isCube = root.GetComponent<CubeCreatorCube>() != null || FindDeep(root.transform, "CubeMesh") != null
                              || (sourcePath != null && sourcePath.Replace('\\', '/').Contains("/CubeCreator_"));
                if (isCube)
                {
                    modelPath = sourcePath;
                    return root;
                }
            }

            // 2) an exported model (or its config) selected in the Project window
            string path = selected != null && EditorUtility.IsPersistent(selected) ? AssetDatabase.GetAssetPath(selected) : null;
            if (!string.IsNullOrEmpty(path) && path.EndsWith(".json") && Path.GetFileName(path).StartsWith(ConfigPrefix))
                path = FindModelNear(path);
            bool exportedModel = !string.IsNullOrEmpty(path) && AssetDatabase.LoadAssetAtPath<GameObject>(path) != null
                                 && path.Replace('\\', '/').Contains("/CubeCreator_");
            // 3) otherwise: the only exported cube in the project
            if (!exportedModel) path = FindOnlyExportedModel();
            if (path == null) return null;

            modelPath = path;
            var asset = AssetDatabase.LoadAssetAtPath<GameObject>(path);
            var instance = (GameObject)PrefabUtility.InstantiatePrefab(asset);
            Undo.RegisterCreatedObjectUndo(instance, "Add Cube Creator cube");
            instance.transform.position = Vector3.zero;
            return instance;
        }

        static Transform FindDeep(Transform t, string name)
        {
            if (t.name == name) return t;
            foreach (Transform c in t)
            {
                var r = FindDeep(c, name);
                if (r != null) return r;
            }
            return null;
        }

        static string FindOnlyExportedModel()
        {
            var configs = AllConfigPaths();
            if (configs.Length == 0)
            {
                EditorUtility.DisplayDialog("Cube Creator",
                    "No exported cubes found.\n\nUnzip the Unity export and drag its CubeCreator_<name> folder into Assets first.", "OK");
                return null;
            }
            if (configs.Length > 1)
            {
                EditorUtility.DisplayDialog("Cube Creator",
                    "Several cubes are in this project.\n\nSelect the one you want (its .glb in the Project window, or the model in your scene), then run Set Up Cube again.", "OK");
                return null;
            }
            string model = FindModelNear(configs[0]);
            if (model == null)
                EditorUtility.DisplayDialog("Cube Creator",
                    "Found the config but not an importable model.\n\nInstall glTFast (Package Manager > + > Add package by name > com.unity.cloud.gltfast) so the .glb imports, or keep the Models/OBJ folder.", "OK");
            return model;
        }

        /// Prefer the .glb (needs glTFast), fall back to the OBJ.
        static string FindModelNear(string configPath)
        {
            string folder = Path.GetDirectoryName(configPath).Replace('\\', '/');
            string name = Path.GetFileNameWithoutExtension(configPath).Replace(ConfigPrefix, "");
            foreach (var candidate in new[] { $"{folder}/Models/{name}.glb", $"{folder}/Models/OBJ/{name}.obj" })
                if (AssetDatabase.LoadAssetAtPath<GameObject>(candidate) != null) return candidate;
            return null;
        }

        // ------------------------------------------------------------------ config

        static string[] AllConfigPaths() =>
            AssetDatabase.FindAssets(ConfigPrefix + " t:TextAsset")
                .Select(AssetDatabase.GUIDToAssetPath)
                .Where(p => Path.GetFileName(p).StartsWith(ConfigPrefix) && p.EndsWith(".json"))
                .ToArray();

        /// The config sitting in the same export folder as the model, else the only/matching one.
        static TextAsset FindConfig(string modelPath)
        {
            var configs = AllConfigPaths();
            if (!string.IsNullOrEmpty(modelPath))
            {
                string modelName = Path.GetFileNameWithoutExtension(modelPath);
                string match = configs.FirstOrDefault(p => Path.GetFileNameWithoutExtension(p) == ConfigPrefix + modelName);
                if (match == null)
                {
                    string dir = Path.GetDirectoryName(modelPath).Replace('\\', '/');
                    match = configs.FirstOrDefault(p => dir.StartsWith(Path.GetDirectoryName(p).Replace('\\', '/')));
                }
                if (match != null) return AssetDatabase.LoadAssetAtPath<TextAsset>(match);
            }
            return configs.Length == 1 ? AssetDatabase.LoadAssetAtPath<TextAsset>(configs[0]) : null;
        }

        // ------------------------------------------------------------------- bloom

        /// URP: add a global Volume with Bloom (if the scene has none) and enable camera
        /// post-processing. Done through reflection so this file compiles in any pipeline.
        static string TryAddBloom(string assetFolder)
        {
            if (GraphicsSettings.currentRenderPipeline == null)
                return "Bloom: Built-in render pipeline – install the Post Processing package (or use URP) for glow halos.";
            try
            {
                Type volumeType = FindType("UnityEngine.Rendering.Volume");
                Type profileType = FindType("UnityEngine.Rendering.VolumeProfile");
                Type bloomType = FindType("UnityEngine.Rendering.Universal.Bloom");
                Type camDataType = FindType("UnityEngine.Rendering.Universal.UniversalAdditionalCameraData");
                if (volumeType == null || profileType == null || bloomType == null)
                    return "Bloom: not URP – add bloom with your pipeline's post-processing.";

                string camNote = "";
                var cam = Camera.main;
                if (cam != null && camDataType != null)
                {
                    var data = cam.GetComponent(camDataType);
                    if (data == null) data = Undo.AddComponent(cam.gameObject, camDataType);
                    var prop = camDataType.GetProperty("renderPostProcessing");
                    if (prop != null)
                    {
                        Undo.RecordObject(data, "Enable post-processing");
                        prop.SetValue(data, true);
                        EditorUtility.SetDirty(data);
                    }
                }
                else camNote = " (no Main Camera found – tick Post Processing on your camera)";

                if (Object.FindObjectsByType(volumeType, FindObjectsSortMode.None).Length > 0)
                    return "Bloom: scene already has a Volume – make sure it has a Bloom override." + camNote;

                var profile = ScriptableObject.CreateInstance(profileType);
                string profilePath = AssetDatabase.GenerateUniqueAssetPath($"{assetFolder}/CubeCreatorBloom.asset");
                AssetDatabase.CreateAsset(profile, profilePath);
                var bloom = (Object)profileType.GetMethod("Add", new[] { typeof(Type), typeof(bool) }).Invoke(profile, new object[] { bloomType, true });
                bloom.name = bloomType.Name;
                AssetDatabase.AddObjectToAsset(bloom, profile);
                SetParameter(bloom, "threshold", 0.9f);
                SetParameter(bloom, "intensity", 1.2f);
                SetParameter(bloom, "scatter", 0.6f);
                EditorUtility.SetDirty(profile);
                AssetDatabase.SaveAssets();

                var go = new GameObject("Cube Creator Bloom");
                Undo.RegisterCreatedObjectUndo(go, "Add bloom volume");
                var volume = go.AddComponent(volumeType);
                SetMember(volume, "isGlobal", true);
                SetMember(volume, "sharedProfile", profile);
                return "Bloom: added a global 'Cube Creator Bloom' volume." + camNote;
            }
            catch (Exception e)
            {
                Debug.LogWarning("[CubeCreator] Bloom setup skipped: " + e);
                return "Bloom: couldn't set up automatically (see Console) – add a Volume with Bloom by hand.";
            }
        }

        static void SetParameter(object component, string field, float value)
        {
            var param = component.GetType().GetField(field)?.GetValue(component);
            if (param == null) return;
            param.GetType().GetProperty("overrideState")?.SetValue(param, true);
            param.GetType().GetProperty("value")?.SetValue(param, value);
        }

        /// Volume members are fields in some URP versions and properties in others.
        static void SetMember(object target, string name, object value)
        {
            var t = target.GetType();
            var field = t.GetField(name);
            if (field != null) { field.SetValue(target, value); return; }
            t.GetProperty(name)?.SetValue(target, value);
        }

        static Type FindType(string fullName) =>
            AppDomain.CurrentDomain.GetAssemblies()
                .Select(a => a.GetType(fullName, false))
                .FirstOrDefault(t => t != null);
    }
}
